/**
* Normalizes phone numbers into E.164 international format.
* Defaults to country code +91 for 10-digit Indian numbers.
*/
function normalizeE164(phone, defaultCountryCode = "91") {
	if (!phone) return "";
	const clean = phone.replace(/\D/g, "");
	if (!clean) return "";
	if (clean.length === 12 && clean.startsWith("91")) return `+${clean}`;
	if (clean.length === 10) return `+${defaultCountryCode}${clean}`;
	if (clean.length > 10) return `+${clean}`;
	return `+${clean}`;
}
/**
* Validates whether a phone number can be targeted for WhatsApp messaging.
*/
function isValidWhatsAppPhone(phone) {
	if (!phone) return false;
	const digits = phone.replace(/\D/g, "");
	return digits.length >= 10 && digits.length <= 15;
}
/**
* Filters patients into Eligible, Opted-Out, and Invalid lists based on Audience criteria.
*/
function calculateAudience(patients, audienceType) {
	const eligible = [];
	const optedOut = [];
	const invalid = [];
	const sixMonthsAgo = /* @__PURE__ */ new Date();
	sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
	const sixMonthsAgoStr = sixMonthsAgo.toISOString().slice(0, 10);
	patients.forEach((p) => {
		if (!isValidWhatsAppPhone(p.phone || "")) {
			invalid.push(p);
			return;
		}
		if (p.whatsappOptOut === true) {
			optedOut.push(p);
			return;
		}
		if (audienceType === "consented_only" && p.whatsappConsent === false) {
			optedOut.push(p);
			return;
		}
		if (audienceType === "recent_patients") {
			const visit = p.lastVisit || "";
			if (!visit || visit < sixMonthsAgoStr) return;
		}
		if (audienceType === "male_only" && (p.gender || "").toLowerCase() !== "male") return;
		if (audienceType === "female_only" && (p.gender || "").toLowerCase() !== "female") return;
		eligible.push(p);
	});
	return {
		eligible,
		optedOut,
		invalid,
		total: patients.length
	};
}
